// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.contactimport com.roshan.persona.connectivity.model.ContactInfoimport com.roshan.persona.connectivity.model.ContactMatchResultimport com.roshan.persona.connectivity.model.MatchTypeimport com.roshan.persona.connectivity.model.MessagingApp/** * NOUS — Contact Searcher (Module 11 v3 — Step 11.1). * * Searches the device's contact list with **fuzzy name matching** — * "mom" → Mom Sharma, "roh" → Rohit Verma, "pri" → Priya Singh. * * ## Search algorithm (3-tier) * *  1. **Exact match** (case-insensitive) — "Mom" == "mom" → instant match. *  2. **Nickname / contains** — "mom" in "Mom Sharma" → match. *  3. **Levenshtein distance** — "roh" vs "Rohit" (distance 3) → fuzzy match. * * Also supports **phone number search** — "+919876" → matches contacts * with that number prefix. * * ## Testability * * [ContactService] is an interface — tests inject a fake. The search * logic (Levenshtein, scoring) is in pure functions — fully testable * without Android. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§ContactEngine</a> */class ContactSearcher(    private val contactService: ContactService,    private val maxFuzzyDistance: Int = 3,    private val maxResults: Int = 10,    private val ftsDao: ContactFtsDao? = null,) {    /**     * Search contacts by name (fuzzy) or phone number.     *     * If the FTS4 mirror is available ([ftsDao] non-null and populated),     * the search runs through Room's FTS4 virtual table for sub-20ms     * performance. Otherwise, falls back to the legacy O(N) in-memory     * Levenshtein scan.     *     * @param query the search query ("mom", "rohit", "+919876").     * @return ranked list of matches (best first), empty if no match.     */    suspend fun search(query: String): List<ContactMatchResult> {        if (query.isBlank()) return emptyList()        // Try FTS4 mirror first.        val ftsResults = tryFtsSearch(query)        if (ftsResults.isNotEmpty()) return ftsResults        // Fallback: legacy O(N) scan.        val allContacts = contactService.getAllContacts()        if (allContacts.isEmpty()) return emptyList()        val lowerQuery = query.lowercase().trim()        val results = mutableListOf<ContactMatchResult>()        for (contact in allContacts) {            val match = matchContact(lowerQuery, contact)            if (match != null) results.add(match)        }        return results            .sortedByDescending { it.matchScore }            .take(maxResults)    }    /**     * Multi-field FTS4 search via [ContactFtsDao].     *     * Parses [query] into a multi-field MATCH expression (e.g.,     * "Mom mobile" → `name:Mom* AND (notes:mobile* OR phone:mobile*)`)     * using [ContactFtsQueryParser], then resolves matching contact IDs     * back to full [ContactInfo]s via [contactService].     */    private suspend fun tryFtsSearch(query: String): List<ContactMatchResult> {        val dao = ftsDao ?: return emptyList()        val matchExpr = ContactFtsQueryParser.parse(query) ?: return emptyList()        val contactIds = try {            dao.search(matchExpr, maxResults)        } catch (t: Throwable) {            timber.log.Timber.tag(TAG).w(t, "FTS search failed — falling back to legacy scan.")            return emptyList()        }        if (contactIds.isEmpty()) return emptyList()        // Resolve IDs → full contacts.        val allContacts = contactService.getAllContacts()        val byId = allContacts.associateBy { it.id }        return contactIds.mapNotNull { id ->            byId[id]?.let { contact ->                ContactMatchResult(contact, 0.95f, MatchType.EXACT)            }        }    }    /**     * Find the single best match for [query].     *     * Returns null if no match meets the threshold.     */    suspend fun findBestMatch(query: String): ContactInfo? {        val matches = search(query)        return matches.firstOrNull()?.contact    }    /**     * Find a contact by phone number (exact match).     *     * @param phoneNumber the phone number to search (normalized — digits only).     * @return the contact, or null if not found.     */    suspend fun findByPhoneNumber(phoneNumber: String): ContactInfo? {        val normalized = normalizePhoneNumber(phoneNumber)        if (normalized.isBlank()) return null        return contactService.getAllContacts().firstOrNull { contact ->            contact.phoneNumbers.any { normalizePhoneNumber(it) == normalized }        }    }    // ─── Matching logic (pure functions) ───────────────────────────────────    internal fun matchContact(query: String, contact: ContactInfo): ContactMatchResult? {        val nameLower = contact.displayName.lowercase().trim()        // 1. Exact match.        if (nameLower == query) {            return ContactMatchResult(contact, 1.0f, MatchType.EXACT)        }        // 2. Contains (query is substring of name or vice versa).        if (nameLower.contains(query) || query.contains(nameLower)) {            return ContactMatchResult(contact, 0.8f, MatchType.NICKNAME)        }        // 3. Phone number match.        val normalizedQuery = normalizePhoneNumber(query)        if (normalizedQuery.length >= 4) {            for (phone in contact.phoneNumbers) {                val normalizedPhone = normalizePhoneNumber(phone)                if (normalizedPhone.contains(normalizedQuery) || normalizedQuery.contains(normalizedPhone)) {                    return ContactMatchResult(contact, 0.9f, MatchType.PHONE_NUMBER)                }            }        }        // 4. Fuzzy match (Levenshtein distance).        val distance = levenshtein(query, nameLower)        if (distance <= maxFuzzyDistance) {            val score = 1.0f - (distance.toFloat() / maxFuzzyDistance.coerceAtLeast(1))            return ContactMatchResult(contact, score * 0.7f, MatchType.FUZZY)        }        return null    }    /** Normalize a phone number — digits only. */    internal fun normalizePhoneNumber(phone: String): String {        return phone.filter { it.isDigit() }    }    /** Levenshtein distance between two strings. */    internal fun levenshtein(a: String, b: String): Int {        val m = a.length        val n = b.length        if (m == 0) return n        if (n == 0) return m        val dp = Array(m + 1) { IntArray(n + 1) }        for (i in 0..m) dp[i][0] = i        for (j in 0..n) dp[0][j] = j        for (i in 1..m) {            for (j in 1..n) {                val cost = if (a[i - 1] == b[j - 1]) 0 else 1                dp[i][j] = minOf(                    dp[i - 1][j] + 1,                    dp[i][j - 1] + 1,                    dp[i - 1][j - 1] + cost,                )            }        }        return dp[m][n]    }    private companion object {        private const val TAG = "ContactSearcher"    }}// ──────────────────────────────────────────────────────────────────────────/** * Contact service interface — wraps ContactsContract. * * Real implementation ([AndroidContactService]) queries the device's * ContactsContract provider. Tests inject a fake. */interface ContactService {    /** Get all contacts from the device. */    suspend fun getAllContacts(): List<ContactInfo>    /** Get a contact by ID. */    suspend fun getContactById(id: String): ContactInfo?    /** Get favorite contacts. */    suspend fun getFavorites(): List<ContactInfo>    /** Get trusted contacts (voice verification bypass list). */    suspend fun getTrustedContacts(): List<ContactInfo>}